		public void Dispose()
		{
#if UNITY_EDITOR
			// Before the group, and before the picking material goes with Destroyed. Unset without the editor hook.
			if (!_picking.Equals(BatchMaterialID.Null))
				_group.UnregisterMaterial(_picking);
			Destroyed?.Invoke(this);
#endif
			if (SlotEntities.IsCreated)
				CollectionHelper.Dispose(SlotEntities);
			if (SlotRadii.IsCreated)
				CollectionHelper.Dispose(SlotRadii);
			if (StaticSlotRadii.IsCreated)
				CollectionHelper.Dispose(StaticSlotRadii);
			if (_isSlotSelected.IsCreated)
				CollectionHelper.Dispose(_isSlotSelected);
			ReleaseStatic();

			// Registry first: unregistering goes through the group.
			_registry.Dispose();
			_group.UnregisterMaterial(_selectionMask);
			_group.Dispose();
			_dynamicBuffer.Dispose();
			_overlayBuffer.Dispose();

			if (_instances.IsCreated)
				CollectionHelper.Dispose(_instances);
			if (_runs.IsCreated)
				CollectionHelper.Dispose(_runs);
			if (_pendingBounds.IsCreated)
				CollectionHelper.Dispose(_pendingBounds);
			if (_overlayInstances.IsCreated)
				CollectionHelper.Dispose(_overlayInstances);
			if (_decalRuns.IsCreated)
				CollectionHelper.Dispose(_decalRuns);
			if (_pendingOverlay.IsCreated)
				_pendingOverlay.Dispose();
		}

void WriteAll()
{
	if (_instanceCount == 0)
		return;

	for (int i = 0; i < _instanceCount; i++)
		WriteMatrix(i);
}

internal void Compact()
{
	for (int i = _instanceCount - 1; i >= 0; i--)
		SwapIntoFree(i);

	_head = 0;
}

